# Independent (exponential-time) ground truth for Lie(R_u(G)), used only to cross-check
# the polynomial-time layered algorithm on small examples.
#
# GT-qu  (b_P(Gamma) finite):   R_u(G) = closure of K = ker(b_P|Gamma); K is generated by
#         Schreier generators; Lie(R_u G) = Lie algebra generated by their logarithms.
# GT-gen (condition (a) holds):  Gamma_B = kernel of the (finite) conjugation action of
#         b_P(Gamma) on B = M_d^{H^o}; with Schreier generators s_i of Gamma_B,
#         Lie(R_u G) = smallest Ad(Gamma)-stable Lie subalgebra containing log (s_i)_u and
#         log [s_i, s_j]   (proof in section_claude.tex, Lemma "gt").
import flint
from linalg_claude import Q, ZERO, ONE, eye, zeros, vec, unvec, is_zero_mat, Subspace, nullspace


def mlog_unip(U):
    d = U.nrows()
    N = U - eye(d)
    R = zeros(d, d)
    T = eye(d)
    for k in range(1, d + 1):
        T = T * N
        if is_zero_mat(T):
            break
        R += Q((-1) ** (k + 1), k) * T
    return R


def jordan_rational(g):
    """(g_s, g_u) for g with rational eigenvalues; raises if not rational."""
    d = g.nrows()
    cp = g.charpoly()
    roots = cp.roots()
    tot = sum(e for (_, e) in roots)
    if tot != d:
        raise ValueError("eigenvalues not rational")
    cols = []
    lams = []
    for (lam, e) in roots:
        A = g - lam * eye(d)
        P = eye(d)
        for _ in range(d):
            P = P * A
        ns = nullspace(P)
        assert len(ns) == e
        for v in ns:
            cols.append(v)
            lams.append(lam)
    P = flint.fmpq_mat(d, d, [cols[j][i] for i in range(d) for j in range(d)])
    D = flint.fmpq_mat(d, d, [lams[i] if i == j else ZERO for i in range(d) for j in range(d)])
    gs = P * D * P.inv()
    gu = gs.inv() * g
    return gs, gu


def lie_closure(seeds, gens, d):
    """smallest Ad(<gens>)-stable Lie subalgebra of M_d(Q) containing seeds."""
    allg = [(g, g.inv()) for g in gens]
    S = Subspace([], d * d)
    mats = []
    queue = list(seeds)
    while queue:
        X = queue.pop()
        if S.contains(vec(X)):
            continue
        S = S.add([vec(X)])
        for Y in mats:
            queue.append(X * Y - Y * X)
        mats.append(X)
        for g, gi in allg:
            queue.append(g * X * gi)
            queue.append(gi * X * g)
    return S


def schreier(act_gens, gamma_gens, limit=50000):
    """Finite group generated by act_gens (matrices); returns Schreier generators of the
    kernel of the map gamma_gens[i] -> act_gens[i], as actual products of gamma_gens."""
    key = lambda X: tuple(X.entries())
    n = act_gens[0].nrows()
    d = gamma_gens[0].nrows()
    reps = {key(eye(n)): (eye(n), eye(d))}
    order = [key(eye(n))]
    i = 0
    while i < len(order):
        h, w = reps[order[i]]
        i += 1
        for a, g in zip(act_gens, gamma_gens):
            h2 = h * a
            k = key(h2)
            if k not in reps:
                reps[k] = (h2, w * g)
                order.append(k)
                if len(order) > limit:
                    raise RuntimeError("finite quotient too large")
    gens = []
    for k in order:
        h, w = reps[k]
        for a, g in zip(act_gens, gamma_gens):
            h2, w2 = reps[key(h * a)]
            s = w * g * w2.inv()
            if not is_zero_mat(s - eye(d)):
                gens.append(s)
    return gens, len(order)


def gt_qu(setup):
    """Lie(R_u G) for quasi-unipotent Gamma (finite b_P(Gamma)); in adapted coordinates."""
    s, order = schreier(setup.bdiag, setup.gens)
    seeds = [mlog_unip(x) for x in s]
    return lie_closure(seeds, setup.gens, setup.d), order


def gt_general(setup, B_mats):
    """Lie(R_u G) under condition (a); B_mats = basis of B = M_d^{H^o}."""
    d = setup.d
    N = d * d
    Bsub = Subspace([vec(X) for X in B_mats], N)
    acts = []
    for b in setup.bdiag:
        bi = b.inv()
        cols = [Bsub.coords(vec(b * X * bi)) for X in [unvec(v, d, d) for v in Bsub.basis]]
        k = Bsub.dim
        acts.append(flint.fmpq_mat(k, k, [cols[j][i] for i in range(k) for j in range(k)]))
    s, order = schreier(acts, setup.gens)
    seeds = []
    for x in s:
        xs, xu = jordan_rational(x)
        seeds.append(mlog_unip(xu))
    for x in s:
        for y in s:
            c = x * y * x.inv() * y.inv()
            seeds.append(mlog_unip(c))
    return lie_closure(seeds, setup.gens, d), order
